begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(13);
set local role authenticated;
set local request.jwt.claims='{"sub":"5eed0000-0000-4000-8000-000000000011","role":"authenticated","aal":"aal1"}';
select lives_ok($$select public.update_my_season_answers(jsonb_build_object('specific_needs',jsonb_build_object('kind','support-needs','version',1,'categories',jsonb_build_array('health','communication'),'details',jsonb_build_object('health',repeat('h',2000),'communication',repeat('w',2000)))::text))$$,'several category explanations fit the encrypted answer');
select is((select (specific_needs::jsonb)->'categories' from public.get_own_profile()),'["health", "communication"]'::jsonb,'canonical categories round-trip');
select throws_ok($$select public.update_my_season_answers(jsonb_build_object('specific_needs','{"kind":"support-needs","version":1,"categories":["none","health"],"details":{}}'))$$,'22023',null::text,'None cannot coexist with another category');
select throws_ok($$select public.update_my_season_answers(jsonb_build_object('specific_needs',jsonb_build_object('kind','support-needs','version',1,'categories',jsonb_build_array('health'),'details',jsonb_build_object('health',repeat('h',2001)))::text))$$,'22023',null::text,'each explanation is limited to 2000 characters');
select lives_ok($$select public.update_my_season_answers('{"specific_needs":"Legacy free-text answer"}')$$,'legacy free text stays valid');
select lives_ok($$select public.update_my_season_answers(jsonb_build_object('specific_needs','{"kind":"support-needs","version":1,"categories":["none"],"details":{}}'))$$,'None is an explicit persisted answer');
select is((select (specific_needs::jsonb)->'categories' from public.get_own_profile()),'["none"]'::jsonb,'None round-trips separately from no answer');
select throws_ok($$select public.update_my_season_answers(jsonb_build_object('specific_needs','{"kind":"support-needs","version":1,"categories":["unknown"],"details":{}}'))$$,'22023',null::text,'unknown categories are rejected');
select throws_ok($$select public.update_my_season_answers(jsonb_build_object('specific_needs',repeat('x',32001)))$$,'22023',null::text,'the whole answer stays bounded');
select lives_ok($$select public.update_my_season_answers(jsonb_build_object('specific_needs','{"kind":"support-needs","version":1,"categories":["accessibility","communication"],"details":{},"explanation":"An accessible room and an interpreter"}'))$$,'combined explanation saves for several categories');
select is((select specific_needs::jsonb->>'explanation' from public.get_own_profile()),'An accessible room and an interpreter','combined explanation round-trips without duplication');
select throws_ok($$select public.update_my_season_answers(jsonb_build_object('specific_needs',jsonb_build_object('kind','support-needs','version',1,'categories',jsonb_build_array('health'),'details','{}'::jsonb,'explanation',repeat('x',2001))::text))$$,'22023',null::text,'combined explanation is limited to 2000 characters');
select throws_ok($$select public.update_my_season_answers(jsonb_build_object('specific_needs','{"kind":"support-needs","version":1,"categories":["none"],"details":{},"explanation":"Hidden answer"}'))$$,'22023',null::text,'None cannot retain a combined explanation');
select * from finish();
rollback;
